namespace PsychologyApp.Application.Articles;

public static partial class ArticleContent
{
    private static readonly Article[] AdditionalArticlesFr =
    [
        MiniArticle(ArticleIds.CallNerves, "Le stress avant un appel", "Rendez le premier appel plus simple", "Ne répétez pas toute la conversation. Notez un objectif et une première phrase. Vous pouvez consulter votre note, demander de répéter ou faire une pause. Réussir, c’est aussi simplement passer l’appel."),
        MiniArticle(ArticleIds.WaitingForReply, "En attendant une réponse", "Le silence dans un message n’explique rien", "Notez trois raisons possibles, dont une neutre, puis choisissez quand vérifier à nouveau. Si c’est urgent, décidez qui contacter et quand au lieu de rafraîchir l’écran."),
        MiniArticle(ArticleIds.AfterSocialEvent, "Après une rencontre, cessez de tout repasser", "Interrompez le film mental de la conversation", "Repérez un moment qui s’est bien passé et une conclusion impossible à tirer pour l’instant. Ne cherchez pas la phrase parfaite après coup. Revenez à votre activité; vous pourrez reprendre un sujet important plus tard."),
        MiniArticle(ArticleIds.FearOfMistakes, "Une erreur n’est pas un verdict", "Définissez ce qui est suffisamment bien", "Avant de commencer, choisissez un résultat suffisant et vérifiez un point important. En cas d’erreur, regardez ses conséquences réelles et le prochain geste réparable. Un faux pas ne vous définit pas entièrement."),
        MiniArticle(ArticleIds.ChangeAnxiety, "Quand le changement inquiète", "Séparez les faits de l’inconnu", "Faites deux colonnes : ce que vous savez et ce que vous pourriez apprendre. Choisissez une question et un moment pour y revenir. Le reste peut attendre; l’incertitude n’annonce pas une mauvaise issue."),
        MiniArticle(ArticleIds.WorryBeforeTask, "Avant une tâche difficile", "Commencez sans attendre une confiance totale", "Décidez de ce qu’il faut pour commencer sans risque : du matériel, dix minutes ou une précision. Commencez par là, puis choisissez si vous continuez. L’anxiété n’a pas besoin de disparaître avant le premier pas."),
        MiniArticle(ArticleIds.AvoidedFirstStep, "Faites seulement le premier pas", "Le démarrage peut durer deux minutes", "Rendez le début minuscule : ouvrir un fichier, écrire un titre ou sortir le matériel. Vous pouvez vous arrêter ensuite. Le but est de faciliter le départ, pas de vous priver d’une pause."),
        MiniArticle(ArticleIds.CheckingLoop, "Vérifier, puis s’arrêter", "Fixez une limite avant de vérifier", "Décidez quoi vérifier et combien de fois. Après la dernière vérification, notez que c’est fait et passez à autre chose. Si l’anxiété insiste, voyez-y une demande de l’anxiété, pas une nouvelle preuve."),
        MiniArticle(ArticleIds.PublicPlaceAnxiety, "L’anxiété dans un lieu public", "Trouvez un repère et gardez le choix", "Sentez l’appui sous vos pieds et nommez quelques objets autour de vous. Repérez un endroit calme. Vous pouvez partir ou demander de l’aide si vous êtes en danger : l’exercice ne doit pas vous retenir."),
        MiniArticle(ArticleIds.MorningWorry, "Un matin sans liste de soucis", "Pas besoin de résoudre toute la semaine au petit-déjeuner", "Notez les soucis et choisissez un besoin réel pour aujourd’hui. Planifiez le reste ou attendez de nouvelles informations. Commencez par un pas, sans essayer de tout prévoir."),
        MiniArticle(ArticleIds.SensoryOverload, "Quand le bruit et l’activité débordent", "Réduisez la charge sur votre attention", "Si possible, retirez une source de bruit, baissez la luminosité ou allez dans un lieu plus calme. Choisissez un repère d’attention. Une pause ne vous oblige pas à reprendre aussitôt votre rythme habituel."),
        MiniArticle(ArticleIds.EveningTension, "Terminez la journée en douceur", "Reportez les tâches inachevées à demain", "Prenez quelques minutes pour noter ce qui est fait, ce qui peut attendre et par quoi commencer demain. Si votre routine a changé, choisissez un repère simple pour le coucher plutôt qu’un rituel rigide."),
        MiniArticle(ArticleIds.AnxietyComedown, "Après une montée d’anxiété", "Récupérez d’abord, réfléchissez ensuite", "Vérifiez que vous êtes en sécurité et laissez-vous le temps de retrouver votre rythme. Une activité simple et familière peut aider. Plus tard, notez ce qui vous a soutenu et ce que vous aimeriez aborder avec un professionnel."),
        MiniArticle(ArticleIds.SafePractice, "Un exercice n’est pas un examen", "Adaptez la pratique à vos besoins", "Vous pouvez raccourcir l’exercice, garder les yeux ouverts, sauter une étape ou arrêter. Si cela devient inconfortable, reprenez votre respiration naturelle et choisissez un autre repère. Inutile de supporter un malaise pour suivre une consigne."),

        MiniArticle(ArticleIds.ThoughtLabel, "Donnez un nom à la pensée", "Remarquez-la sans la contredire", "Essayez : « Je remarque la pensée que… ». Cela ne prouve pas qu’elle est fausse, mais aide à la voir comme une pensée. Demandez-vous ensuite quelle petite action correspond à votre tâche ou à vos valeurs."),
        MiniArticle(ArticleIds.MindReading, "Ne devinez pas les pensées des autres", "Séparez l’observation de l’interprétation", "Notez ce que la personne a dit ou fait, puis ce que vous en avez déduit. Si la réponse compte, demandez une précision calmement. Sinon, laissez la question ouverte au lieu de prendre une supposition pour un fait."),
        MiniArticle(ArticleIds.WorstVsLikely, "Le pire n’est pas le plus probable", "Envisagez plusieurs possibilités", "Notez la pire issue, la meilleure et la plus plausible. Préparez-vous à la plus plausible; pour la pire, faites un seul plan raisonnable si nécessaire. Ne consacrez pas toute votre énergie à chaque scénario imaginé."),
        MiniArticle(ArticleIds.EvidenceAndUnknown, "Ce que je sais et ce que j’ignore", "Ne remplissez pas un vide par une inquiétude", "Faites deux colonnes : « Je sais » et « Je ne sais pas encore ». Pour l’inconnu, choisissez comment obtenir une réponse ou quand réexaminer la question. Si rien n’est possible aujourd’hui, laissez-la ouverte."),
        MiniArticle(ArticleIds.NegativityFilter, "Remarquez aussi ce qui s’est bien passé", "Ajoutez un fait au tableau", "Après un moment difficile, l’esprit voit les erreurs et oublie les instants ordinaires ou réussis. Nommez un fait qui ne correspond pas à la version négative. Il ne faut pas prétendre que tout va bien, seulement voir l’ensemble."),
        MiniArticle(ArticleIds.ConversationReplay, "Arrêtez de rejouer la conversation sans fin", "Décidez s’il existe une prochaine étape", "Demandez-vous s’il y a un problème précis à réparer. Si oui, notez une prochaine action courte. Sinon, reconnaissez la répétition et revenez à ce que vous voyez, entendez ou faites maintenant."),
        MiniArticle(ArticleIds.DecisionFatigue, "Simplifiez un petit choix", "Décidez à l’avance de ce qui suffit", "Pour les choix répétitifs, utilisez une règle simple : budget, durée ou critère de qualité. Appliquez-la sans comparer toutes les options à l’infini. Pour une décision importante, prenez séparément le temps de réunir les faits."),
        MiniArticle(ArticleIds.GoodEnough, "Suffisamment bien, c’est déjà un résultat", "Limitez les retouches inutiles", "Choisissez deux critères indispensables et une heure d’arrêt. Quand ils sont remplis, enregistrez ou envoyez le travail. Retouchez encore seulement pour corriger un problème concret, pas pour viser l’impossible perfection."),
        MiniArticle(ArticleIds.ControlInfluence, "Ce que je peux influencer", "Concentrez-vous sur une action accessible", "Dessinez deux cercles : ce qui dépend de vous et ce qui n’en dépend pas. Choisissez un pas dans le premier; pour l’autre, pensez à une limite, un soutien ou à tolérer l’incertitude. Cela n’efface pas les injustices réelles."),
        MiniArticle(ArticleIds.SelfTalkReset, "Changez le ton de votre dialogue intérieur", "Soyez respectueux et précis avec vous-même", "Remplacez « j’ai encore tout gâché » par une action : « J’ai raté le délai; je vais demander ce qui peut être corrigé ». Cela n’excuse pas l’erreur, mais aide à avancer sans vous insulter."),
        MiniArticle(ArticleIds.WorryAboutWorry, "S’inquiéter de son inquiétude", "Ne vous obligez pas à vous calmer sur-le-champ", "Quand vous pensez « je ne devrais pas ressentir ça », reconnaissez une deuxième vague d’inquiétude. Laissez la première réaction exister et revenez à la tâche proche. Si l’anxiété gêne souvent votre vie, parlez-en à un professionnel."),
        MiniArticle(ArticleIds.CompareHighlightReel, "Ne comparez pas votre vie à une vitrine", "Un fil montre des moments choisis, pas une vie entière", "Une publication n’est qu’un fragment de la journée de quelqu’un. Si la comparaison vous pèse, faites une pause et choisissez votre propre repère : ce qui compte pour vous, pas ce qui impressionne."),
        MiniArticle(ArticleIds.IntrusiveThoughts, "Une pensée indésirable n’est pas une intention", "Regardez les actes et le contexte, pas la pensée seule", "Une pensée inquiétante peut effrayer parce qu’elle ne correspond pas à vos souhaits. Vous n’avez pas à vous tester sans cesse. Remarquez-la et revenez à votre activité; si elle vous gêne beaucoup, demandez un soutien professionnel."),
        MiniArticle(ArticleIds.OneThingAtATime, "Une tâche à la fois", "Réduisez le coût des changements de contexte", "Notez ce qui réclame votre attention et choisissez une tâche pour un court moment. Fermez les onglets ou alertes en trop si possible. Les autres tâches ne disparaissent pas : elles attendent leur tour."),

        MiniArticle(ArticleIds.MoodMovement, "Un peu de mouvement quand l’énergie manque", "L’action n’a pas à attendre une meilleure humeur", "Choisissez un mouvement accessible pendant deux minutes : vous étirer, marcher dans la pièce ou regarder dehors. Remarquez ensuite votre état. C’est un essai, pas une obligation de faire du sport ou d’aller mieux."),
        MiniArticle(ArticleIds.PleasureMastery, "Plaisir et sentiment d’accomplissement", "Repérez différentes activités qui soutiennent", "Vous pouvez prévoir une activité agréable et une petite tâche qui donne un sentiment d’achèvement. Elles peuvent se confondre. Si cela ne se fait pas, c’est une information sur votre charge, pas une raison de vous blâmer."),
        MiniArticle(ArticleIds.EnergyBudget, "Répartissez aussi votre énergie", "Laissez de la place à la récupération", "Repérez les activités qui demandent le plus d’énergie. Si possible, placez une courte pause ou une tâche plus facile entre elles. Un planning avec une marge est souvent plus réaliste qu’un programme sans pause."),
        MiniArticle(ArticleIds.RestBreak, "Faire une pause sans culpabiliser", "Le repos aide à choisir la suite", "Choisissez une courte pause et ce qui vous repose : silence, eau, étirements ou regarder au loin. N’en faites pas une tâche de plus. Si la charge ne laisse aucune place au repos, la discipline n’est pas le seul problème."),
        MiniArticle(ArticleIds.StartFriction, "Retirez un obstacle avant de commencer", "Préparez le départ à l’avance", "Repérez ce qui bloque souvent : chercher un fichier, trop d’étapes ou une consigne floue. Préparez seulement le prochain élément : ouvrez le document, sortez le matériel ou écrivez une question."),
        MiniArticle(ArticleIds.TransitionRitual, "Passer d’une tâche à l’autre", "Une courte pause clarifie l’étape suivante", "Avant de changer d’activité, arrêtez-vous une minute : fermez le fichier précédent, notez ce qui reste et nommez la suite. Ce n’est pas un rituel obligatoire ni une course à la productivité, juste une transition claire."),
        MiniArticle(ArticleIds.TaskActivation, "Quand il est difficile de commencer", "L’action peut précéder la motivation", "Choisissez une action visible de moins de cinq minutes; utilisez un minuteur seulement s’il aide. À la fin, décidez si vous continuez. La motivation peut venir après le départ, mais vous n’avez pas à forcer."),
        MiniArticle(ArticleIds.GentleRoutine, "Une routine souple, pas parfaite", "Gardez un repère stable dans la journée", "Choisissez un petit repère répétable, par exemple planifier après le petit-déjeuner. Si l’horaire change, gardez l’ordre plutôt que la minute exacte. Une journée manquée ne vous empêche pas de reprendre."),
        MiniArticle(ArticleIds.WakeAtNight, "Si vous vous réveillez la nuit", "Restez au calme sans surveiller l’heure", "Essayez de ne pas juger la nuit minute par minute. Si rester au lit est désagréable, une activité calme sous une lumière douce peut aider avant de revenir quand le sommeil revient. Parlez à un professionnel si le problème persiste."),
        MiniArticle(ArticleIds.SmallDayPlan, "Un programme de journée avec de la marge", "Choisissez l’essentiel et prévoyez les imprévus", "Notez une tâche importante, une petite tâche et une pause. Le reste est facultatif si le temps et l’énergie le permettent. Vous pouvez modifier le plan sans vous trahir."),
        MiniArticle(ArticleIds.AskForHelpTask, "Demandez de l’aide pour une partie précise", "Une demande claire évite les devinettes", "Au lieu de « aide-moi », nommez une action et un délai : « Peux-tu relire ce paragraphe aujourd’hui ? » Précisez le résultat utile. Il est plus facile de répondre et de voir si l’aide convient."),
        MiniArticle(ArticleIds.MeaningfulActivity, "Une activité qui a du sens pour vous", "Reliez un petit geste à une valeur", "Demandez-vous ce qui compte ici : le soin, la curiosité, la fiabilité ou le repos. Choisissez une petite action dans cette direction. Elle peut avoir du sens sans tout changer d’un coup."),
        MiniArticle(ArticleIds.FlexibleGoals, "Modifier le plan sans abandonner le but", "Adaptez le pas à votre énergie du jour", "Si le plan est trop lourd, réduisez-le ou changez de méthode. Gardez la direction, pas forcément la forme : dix minutes au lieu d’une heure, un brouillon plutôt qu’un résultat parfait. Le but peut rester souple."),
        MiniArticle(ArticleIds.CelebrateCompletion, "Remarquez ce qui est déjà fait", "L’esprit passe souvent à la tâche suivante", "Après avoir terminé, nommez brièvement ce que vous avez fait et l’effort fourni. Pas besoin de récompense : constater le fait suffit. Vous verrez aussi les tâches accomplies, pas seulement celles qui restent."),

        MiniArticle(ArticleIds.NameEmotion, "Nommez l’émotion plus précisément", "Un mot aide à choisir une réponse", "Au lieu de « ça ne va pas », essayez « tendu », « déçu », « inquiet » ou « fatigué ». Vous pouvez hésiter : ce n’est pas un test. Demandez-vous ensuite ce qu’il vous faut : sécurité, pause, clarté ou lien."),
        MiniArticle(ArticleIds.MixedFeelings, "Deux émotions différentes peuvent coexister", "Des sentiments mêlés ne vous rendent pas incohérent", "On peut être heureux d’un changement et regretter ce qui existait avant. Nommez les deux côtés sans choisir tout de suite. Demandez lequel a besoin d’attention maintenant et offrez-lui un petit geste de soin."),
        MiniArticle(ArticleIds.AngerPause, "Faire une pause avant de répondre avec colère", "La sécurité d’abord, les mots ensuite", "Si la conversation s’envenime, proposez une pause et dites quand vous pourrez reprendre. Allez dans un endroit sûr et laissez-vous du temps. En cas de risque de violence, cherchez un lieu sûr et de l’aide."),
        MiniArticle(ArticleIds.ShameKindness, "Répondre à la honte sans vous humilier", "Réparez une erreur sans vous punir", "Dites-vous : « J’ai honte maintenant, mais ce sentiment ne résume pas qui je suis ». Séparez l’acte de votre identité : que s’est-il passé et peut-on réparer ? Choisissez la réponse que vous offririez à un proche."),
        MiniArticle(ArticleIds.GuiltRepair, "Culpabilité : réparer ou laisser partir", "Distinguez responsabilité et reproches sans fin", "Si vous avez blessé quelqu’un, pensez à une réparation précise et à des excuses respectueuses. Sinon, la culpabilité peut être un sentiment, pas une preuve. Dans les deux cas, vous punir sans fin n’aide pas la personne blessée."),
        MiniArticle(ArticleIds.EnvyInformation, "L’envie peut indiquer ce que vous désirez", "Transformez la comparaison en direction personnelle", "Demandez-vous ce qui vous fait envie : liberté, reconnaissance, proximité ou compétence ? Cela ne fait pas de vous une mauvaise personne. Faites un petit pas vers ce besoin sans copier la vie de l’autre."),
        MiniArticle(ArticleIds.AllowSadness, "La tristesse n’a pas à disparaître tout de suite", "Accueillez-la et choisissez un soutien", "Nommez la perte ou la déception sans vous forcer à aller bien. Demandez-vous ce qui serait doux maintenant : rester seul, écrire à un proche ou faire une petite tâche nécessaire. Si cela gêne durablement votre vie, demandez de l’aide."),
        MiniArticle(ArticleIds.Numbness, "Quand il est difficile de ressentir", "Ne vous forcez pas à vous ouvrir d’un coup", "L’engourdissement peut être une réponse à la surcharge, mais n’en explique pas la cause. Commencez par quelque chose de neutre : où vous êtes, ce que vous voyez et ce que vous voulez dans dix minutes. Si cela inquiète ou dure, parlez-en à un professionnel."),
        MiniArticle(ArticleIds.EmotionWave, "Une émotion peut changer, pas forcément tout de suite", "Observez-la sans chronomètre", "Évaluez l’intensité de zéro à dix et nommez l’émotion. Vous pourrez vérifier plus tard sans exiger une baisse. Le but est de remarquer un mouvement et de garder le choix, pas de mesurer le retour au calme."),
        MiniArticle(ArticleIds.BodyNoticingChoice, "Écoutez votre corps à votre rythme", "Un repère extérieur est aussi possible", "Si remarquer les sensations vous gêne, ne vous forcez pas. Regardez un objet stable, sentez le soutien de la chaise ou nommez les sons. L’attention au corps est une option, pas une condition de l’auto-aide."),
        MiniArticle(ArticleIds.PauseBeforeReact, "Une pause entre l’impulsion et l’action", "Choisissez une réponse moins regrettable", "Si vous voulez envoyer un message tout de suite, attendez quelques minutes si c’est sans danger. Nommez son but et gardez les mots nécessaires. Si attendre risque de nuire, agissez : la pause doit aider, pas gêner."),
        MiniArticle(ArticleIds.EmotionalBoundary, "Les émotions des autres ne sont pas à réparer par vous", "Vous pouvez écouter tout en gardant vos limites", "Vous pouvez écouter sans tout accepter ni promettre de résoudre le problème. Demandez si la personne veut du soutien ou un conseil et dites ce que vous pouvez offrir. L’empathie n’exige pas d’abandonner vos besoins."),
        MiniArticle(ArticleIds.FeelingNotAction, "Une émotion n’impose pas un geste", "Il existe un choix entre ressenti et comportement", "On peut être en colère sans insulter, avoir peur et demander une pause, ou être jaloux sans vérifier les messages. Nommez l’impulsion, puis choisissez une action qui tient compte de votre émotion et de la sécurité d’autrui."),
        MiniArticle(ArticleIds.AfterCrying, "Après avoir pleuré", "Prenez soin de la minute qui vient", "Vous pouvez vous laver le visage, rester assis, respirer normalement, demander de l’eau ou contacter un proche. Inutile d’expliquer les larmes tout de suite. Si vous êtes en danger ou ne pouvez pas rester en sécurité, demandez une aide urgente."),

        MiniArticle(ArticleIds.SpecificRequest, "Demandez quelque chose de précis", "Une demande claire laisse la place à une réponse", "Dites ce qui s’est passé, ce dont vous avez besoin et pour quand. Par exemple : « Je ne peux pas préparer les documents à temps; peux-tu prendre cette partie avant vendredi ? » L’autre peut refuser; vous pourrez chercher une autre option."),
        MiniArticle(ArticleIds.ListenReflect, "Comprendre d’abord, répondre ensuite", "Une brève reformulation peut réduire la tension", "Reformulez ce que vous avez compris et demandez si c’est juste. Ne donnez pas de conseil sans qu’on vous le demande. Même en désaccord, vous pouvez montrer que le message a été entendu."),
        MiniArticle(ArticleIds.BoundarySentence, "Une phrase pour poser une limite", "Une réponse courte est souvent plus claire qu’une longue défense", "Essayez : « Je ne peux pas m’en charger maintenant » ou « Ce ton ne me convient pas; je reprendrai quand nous pourrons parler calmement ». Adaptez la phrase à votre situation et à votre sécurité."),
        MiniArticle(ArticleIds.NoWithoutEssay, "Vous pouvez dire non sans long discours", "Choisissez une formule polie et claire", "Vous pouvez dire « Merci, mais je ne peux pas » ou « Cela ne me convient pas ». Proposez autre chose seulement si vous le souhaitez. En situation risquée, un refus direct n’est pas toujours la meilleure option."),
        MiniArticle(ArticleIds.DifficultTalkOpening, "Commencez une conversation difficile par un objectif", "Parlez d’un fait et d’une demande", "Choisissez un moment calme, nommez une situation précise et dites ce que vous souhaitez. Par exemple : « Les changements de programme sans prévenir me compliquent la tâche; pouvons-nous nous prévenir plus tôt ? » Ne le faites pas si ce n’est pas sûr."),
        MiniArticle(ArticleIds.RepairAfterConflict, "Reprendre après une dispute", "Faites un petit pas vers la clarté", "Quand vous êtes prêts tous les deux, nommez votre part et demandez comment l’autre a vu la situation. Il n’est pas nécessaire de tout résoudre d’un coup. Si l’échange redevient dangereux, arrêtez et cherchez du soutien."),
        MiniArticle(ArticleIds.ApologyResponsibility, "S’excuser sans renoncer à ses limites", "Nommez l’acte et ce que vous changerez", "Une excuse utile est précise : « Je t’ai interrompu; la prochaine fois, je t’écouterai ». Évitez d’ajouter « mais toi… ». Reconnaître votre erreur n’oblige pas à accepter toutes les accusations ni à renoncer à votre sécurité."),
        MiniArticle(ArticleIds.FeedbackAsInformation, "Séparez un retour de votre valeur", "Précisez ce qui peut vous être utile", "Repérez l’action concrète à changer et demandez un exemple si le retour est flou. Un résultat ne juge pas toute votre personne. Une insulte ne devient pas un retour utile parce qu’elle est appelée critique."),
        MiniArticle(ArticleIds.ReceiveNo, "Quand quelqu’un répond non", "Un refus à une demande n’est pas toujours un rejet de vous", "Séparez la réponse à une demande précise de ce que vous en concluez sur vous. Si c’est approprié, demandez s’il existe un autre moment ou une autre option. Vous pouvez être déçu et chercher du soutien ailleurs."),
        MiniArticle(ArticleIds.CheckAssumption, "Vérifiez une supposition par une question", "Clarifiez avant de construire une histoire", "Si un message est ambigu, demandez sans accusation : « Ai-je bien compris que… ? » C’est plus utile que de répondre à un sous-entendu supposé. Sans possibilité de demander, séparez le fait de l’hypothèse et attendez avant de conclure."),
        MiniArticle(ArticleIds.AskSupport, "Demander du soutien s’apprend", "Dites ce qui vous aiderait", "Vous pouvez demander une écoute, une promenade ensemble ou de l’aide pour une tâche. Précisez si vous voulez des idées ou seulement une présence. Si la personne ne peut pas aider, vos besoins ne sont pas pour autant excessifs."),
        MiniArticle(ArticleIds.SupportWithoutFixing, "Être présent sans tout résoudre", "Demandez quel soutien serait utile", "Essayez : « Tu veux que j’écoute, que je reste avec toi ou qu’on réfléchisse à la suite ? » Ne promettez pas ce que vous ne pouvez pas tenir. Le soutien respecte le choix de l’autre et vos limites."),
        MiniArticle(ArticleIds.ConflictNotFailure, "Un désaccord ne signifie pas toujours la fin d’une relation", "Observez la manière dont vous vous traitez", "Comptent aussi le respect, la possibilité de faire une pause et la volonté de parler des conséquences. Vous n’avez pas à accepter des menaces ou de la violence pour « sauver la relation » : la sécurité passe d’abord."),
        MiniArticle(ArticleIds.MakeExpectationsClear, "Exprimez vos attentes à l’avance", "N’attendez pas que l’autre devine", "Avant un projet commun, clarifiez les délais, les rôles et le résultat attendu. Vérifiez que vous avez compris l’accord de la même façon. Cela ne garantit pas l’accord, mais révèle les différences plus tôt."),
        MiniArticle(ArticleIds.DigitalBoundaries, "Poser des limites dans les messages", "Les notifications n’ont pas à diriger la journée", "Choisissez quand répondre et désactivez les alertes non essentielles si vous le souhaitez. Vous pouvez dire à vos proches quand vous êtes généralement disponible. Gardez un moyen distinct de vous joindre en urgence."),
        MiniArticle(ArticleIds.FamilyPressure, "Quand la famille insiste avec des conseils", "Remerciez et dites que vous déciderez", "Essayez : « Je vois que tu t’inquiètes. Je vais y réfléchir et décider ». Si la discussion continue, répétez la phrase ou changez de sujet. Choisissez cette approche seulement si elle n’accroît pas le risque pour vous."),
        MiniArticle(ArticleIds.FriendshipInvitation, "Proposer un moment sans grand programme", "Une petite invitation est plus facile à accepter ou refuser", "Proposez quelque chose de précis et sans pression : « Ça te dirait une promenade jeudi après le travail ? » Ajoutez qu’un autre moment ou un refus convient. La réponse indique sa disponibilité, pas votre valeur."),
        MiniArticle(ArticleIds.SmallConnection, "Un petit contact compte aussi", "Pas besoin de commencer par une conversation profonde", "Si vous vous sentez seul, choisissez une façon simple d’être avec des gens : un message bref, un lieu familier ou une conversation neutre. Arrêtez quand cela suffit. Le but est d’essayer, pas de vous forcer à être sociable."),

        MiniArticle(ArticleIds.OrientNow, "Vérifiez où vous êtes maintenant", "Une façon douce de revenir au présent", "Regardez autour de vous et nommez le lieu, la date ou le moment de la journée, quelques objets et ce qui se passe maintenant. Gardez les yeux ouverts et allez à votre rythme. Si cela augmente l’anxiété, choisissez un objet neutre ou demandez du soutien."),
        MiniArticle(ArticleIds.GroundingChoice, "Choisissez un ancrage qui vous convient", "Se concentrer sur le corps ne convient pas à tout le monde", "Nommez des couleurs, décrivez un objet, sentez la chaise ou écoutez un son régulier. Choisissez un élément supportable maintenant. S’il vous met mal à l’aise, arrêtez et essayez autre chose."),
        MiniArticle(ArticleIds.AfterNightmare, "Après un rêve pénible", "Rappelez-vous que le rêve est terminé", "Allumez une lumière douce, regardez autour et nommez quelques signes que vous êtes dans votre chambre. Inutile de vous souvenir du rêve en détail. Si les cauchemars reviennent ou perturbent le sommeil, parlez-en à un professionnel de santé."),
        MiniArticle(ArticleIds.AnniversaryReaction, "Dates difficiles et anniversaires", "La réaction peut survenir avant ou après la date", "Si une date rappelle un événement pénible, prévoyez moins de tâches et choisissez un soutien à l’avance. Vous pouvez marquer la journée à votre façon ou pas du tout. Des émotions fortes ne signifient pas un retour au début."),
        MiniArticle(ArticleIds.PaceRecovery, "Récupérez à votre rythme", "Ne transformez pas le soin de soi en marathon", "Choisissez une pratique supportable et une durée qui vous convient. Vous pouvez l’arrêter ou changer de méthode. Observez votre humeur, mais aussi si vous vous sentez plus à l’aise ou en sécurité."),
        MiniArticle(ArticleIds.SafetyFirst, "La sécurité passe avant l’exercice", "L’auto-aide ne demande pas de rester en danger", "S’il y a une menace, essayez d’abord d’aller dans un endroit plus sûr et contactez quelqu’un qui peut aider. La respiration et l’ancrage ne remplacent ni la protection, ni les soins médicaux, ni les urgences."),
        MiniArticle(ArticleIds.ChooseTrustedPerson, "Choisissez une personne à contacter", "Pensez à quelqu’un à qui parler simplement", "Nommez une personne qui respecte généralement vos limites. Préparez une phrase : « Je traverse un moment difficile; peux-tu rester en contact ? » Si personne n’est disponible, contactez un professionnel ou un service local."),
        MiniArticle(ArticleIds.AfterStressRecovery, "Après un événement stressant", "Laissez-vous le temps de reprendre les activités ordinaires", "Après une journée difficile, choisissez une action de base et une activité calme : manger, vous changer, rester en silence ou écrire à un proche. Ne vous obligez pas à tout expliquer ou à retrouver tout de suite votre productivité."),
        MiniArticle(ArticleIds.FlashbackGrounding, "Quand le passé semble proche", "Revenez au présent en gardant le choix", "Regardez autour et nommez le lieu et la date si cela aide. Choisissez un objet visible ou contactez quelqu’un près de vous. Ne vous forcez pas à fermer les yeux, respirer profondément ou raconter les détails; cherchez de l’aide réelle en cas de danger."),
        MiniArticle(ArticleIds.RecoveryNotLinear, "La récupération n’est pas linéaire", "Une journée difficile n’efface pas votre chemin", "Ne vous comparez pas à une progression parfaite; regardez ce qui vous aide aujourd’hui. Des émotions fortes peuvent revenir après une période meilleure. Si la situation se dégrade ou devient difficile à gérer, demandez de nouveau du soutien."),

        MiniArticle(ArticleIds.BreathIsOptional, "L’exercice de respiration est facultatif", "Ne vous forcez pas à changer votre souffle", "Si vous concentrer sur le souffle est désagréable, laissez-le naturel et choisissez un repère extérieur : couleur, son ou objet. La respiration ne convient pas à tout le monde et ne remplace pas des soins pour un essoufflement important ou un symptôme nouveau."),
        MiniArticle(ArticleIds.GroundingCanChange, "Si l’ancrage n’aide pas", "Changez de méthode ou arrêtez", "Un exercice ne doit pas fonctionner à chaque fois. Essayez un repère extérieur plus simple, demandez à quelqu’un de décrire la pièce ou terminez l’exercice. Une tentative difficile ne signifie pas que vous l’avez mal faite."),
        MiniArticle(ArticleIds.MovementAnchor, "Le mouvement comme ancrage", "Un petit geste peut rendre un choix", "Si c’est confortable et sûr, ouvrez et fermez lentement les mains ou déplacez votre poids. Vous pouvez aussi regarder un objet bouger. Ne forcez pas malgré la douleur; choisissez un objet immobile si c’est mieux."),
        MiniArticle(ArticleIds.SensesAnchor, "Un repère par les sens", "Choisissez un signal neutre autour de vous", "Nommez une couleur, la température de l’air ou un son régulier qui ne vous dérange pas. Inutile de trouver cinq choses ou de fermer les yeux. Un signal neutre suffit parfois; changez-en s’il est désagréable."),
        MiniArticle(ArticleIds.EarlyStressSigns, "Repérez les premiers signes de surcharge", "Les voir tôt ouvre davantage d’options", "Pensez à ce qui change d’abord : débit de parole, tension, attention ou envie de tout annuler. Notez ce signe et une réponse douce : pause, précision ou demande d’aide. C’est une observation, pas un diagnostic."),
        MiniArticle(ArticleIds.RelaxWithoutForce, "Se détendre sans effort", "Vous n’avez pas à devenir parfaitement calme", "Choisissez un geste qui demande peu de concentration : baisser les épaules, vous installer mieux ou desserrer les mains. Laissez la respiration naturelle. Un peu de confort suffit; ne forcez pas votre corps à se relâcher entièrement."),
        MiniArticle(ArticleIds.BasicCareWithoutRules, "Prendre soin de soi sans règles strictes", "Choisissez ce qui manque maintenant", "Demandez-vous ce qui vous ferait du bien dans l’heure : eau, nourriture, chaleur, calme, mouvement ou contact. Choisissez seulement ce qui est disponible. Si c’est impossible, ne vous blâmez pas : il vous manque peut-être du soutien ou des conditions adaptées."),
        MiniArticle(ArticleIds.NewSymptomsCare, "Symptômes nouveaux ou inhabituels", "Ne posez pas un diagnostic à partir d’un article", "Si des symptômes physiques sont nouveaux, intenses ou évoluent vite, contactez un professionnel de santé. En cas de signes d’urgence, appelez les services locaux. Un exercice d’auto-aide ne doit pas retarder une évaluation médicale."),
        MiniArticle(ArticleIds.FindTherapist, "Comment chercher un professionnel", "Cherchez une bonne relation de travail, pas une description parfaite", "Demandez la formation, l’expérience sur votre sujet, le format, le coût et la confidentialité. Lors du premier rendez-vous, demandez comment le travail se déroule et comment en évaluer l’utilité. Vous pouvez chercher quelqu’un d’autre si le contact ne convient pas."),
        MiniArticle(ArticleIds.FirstAppointment, "Le premier rendez-vous", "Vous n’avez pas à préparer un récit parfait", "Notez deux sujets importants et des questions sur les séances. Vous pouvez dire « j’ai du mal à l’expliquer » et commencer par un exemple récent. Demandez une pause ou ce qui reste confidentiel."),
        MiniArticle(ArticleIds.DescribeSymptoms, "Décrire ce qui se passe", "Un exemple concret vaut mieux que des termes parfaits", "Dites quand cela a commencé, à quelle fréquence et ce qui change au quotidien. Si parler est difficile, apportez une note. Vous n’avez pas à deviner un diagnostic pour demander de l’aide."),
        MiniArticle(ArticleIds.SelfHelpLimits, "Quand l’auto-aide ne suffit pas", "Le soutien professionnel est une prochaine étape valable", "Si votre état perturbe durablement le sommeil, le travail, les études ou les soins personnels, s’aggrave ou résiste aux exercices, contactez un professionnel de santé ou un psychologue. Pas besoin de prouver que vous avez tout essayé seul."),

        MiniArticle(ArticleIds.ScreeningNotDiagnosis, "Un questionnaire n’est pas un diagnostic", "Un résultat peut ouvrir une discussion, pas vous étiqueter", "Les réponses reflètent une période précise et dépendent aussi des circonstances. Montrez le résultat à un professionnel s’il vous inquiète. Ne modifiez pas un traitement et ne prenez pas de décision majeure à partir d’un score seul."),
        MiniArticle(ArticleIds.SupportPlan, "Préparez un petit plan de soutien", "Notez les signes, les étapes et les contacts", "Notez comment vous voyez que cela devient difficile, ce qui aide habituellement et à qui en parler. Ajoutez les contacts professionnels et les urgences locales. Le plan ne remplace pas l’aide; il indique qui joindre quand penser devient difficile."),
        MiniArticle(ArticleIds.CrisisSteps, "Si vous n’êtes pas en sécurité maintenant", "Contactez une aide en direct", "Allez dans un lieu plus sûr si possible et contactez les services d’urgence locaux ou une personne de confiance. Dites brièvement ce qui se passe et où vous êtes. Ne restez pas seul en cas de danger immédiat."),
        MiniArticle(ArticleIds.MedicationWithClinician, "Parlez des médicaments avec un professionnel", "Ne changez pas seul une prescription", "En cas de doute, notez le nom du médicament, votre question et tout effet indésirable, puis parlez-en au prescripteur ou au pharmacien. Ne commencez, n’arrêtez et ne modifiez pas une dose sur la foi d’un article ou d’une application."),
    ];
}
